func (s DiveStruct) JSONSize() int {
	size := 67
	if n := len(s.Scores); n > 0 {
		size += n - 1
	}
	size += len(s.Scores) * 20
	if n := len(s.Tags); n > 0 {
		size += n - 1
	}
	for i0 := range s.Tags {
		size += len(s.Tags[i0])*2 + 2
	}
	size += len(s.Title) * 2
	return size
}

func (s DiveStruct) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"count\":"...)
	dst = strconv.AppendInt(dst, int64(s.Count), 10)
	dst = append(dst, ",\"scores\":"...)
	if s.Scores == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		if len(s.Scores) > 0 {
			dst = strconv.AppendInt(dst, int64(s.Scores[0]), 10)
			for _, v0 := range s.Scores[1:] {
				dst = append(dst, ',')
				dst = strconv.AppendInt(dst, int64(v0), 10)
			}
		}
		dst = append(dst, ']')
	}
	dst = append(dst, ",\"tags\":"...)
	if s.Tags == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		if len(s.Tags) > 0 {
			dst = append(dst, '"')
			dst = ggen.AppendStringNoHTML(dst, s.Tags[0])
			for _, v0 := range s.Tags[1:] {
				dst = append(dst, ",\""...)
				dst = ggen.AppendStringNoHTML(dst, v0)
			}
		}
		dst = append(dst, ']')
	}
	dst = append(dst, ",\"title\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Title)
	return append(dst, '}'), nil
}

